/* Normalise un code de point vers la clé canonique de LVPOINTS (ex: "V13","13 V","v13" -> "13V") */
window.lvPtKey=function(code){
  if(!code)return null;
  var c=String(code).replace(/\s+/g,"").replace(/·.*$/,"");
  if(window.LVPOINTS[c])return c;
  var m=c.match(/^([0-9]{1,2})([A-Za-z]{1,3})$/);
  if(m){var k=m[1]+m[2]; if(window.LVPOINTS[k])return k;}
  m=c.match(/^([A-Za-z]{1,3})([0-9]{1,2})$/);
  if(m){
    var fam=m[1], num=m[2];
    var MAP={"v":"V","p":"P","gi":"GI","e":"E","rte":"Rte","c":"C","ig":"IG","rn":"Rn","mc":"MC","tr":"TR","vb":"VB","f":"F","dm":"DM","rm":"RM"};
    var f=MAP[fam.toLowerCase()]; if(!f)return null;
    var k=num+f; if(window.LVPOINTS[k])return k;
  }
  return null;
};
